        )
    lexer = _Lexer(text)
    return _Parser(text, lexer, frozenset(properties)).parse_describe()


def _all_patterns(clauses) -> List[Tuple[Any, Any, Any]]:
    """按子句顺序取出全部三元组模式（含 OPTIONAL 块与 UNION 分支内模式）。"""
    patterns: List[Tuple[Any, Any, Any]] = []
    for kind, group, _ in clauses:
        if kind == _CLAUSE_FILTER:
            continue
        if kind == _CLAUSE_UNION:
            for branch in group:
                patterns.extend(branch)
        else:
            patterns.extend(group)
    return patterns


def _star_variables(clauses) -> Tuple[str, ...]:
    """按模式从左到右、首次出现的顺序收集全部变量（谓语为路径，不含变量）。"""
    order: List[str] = []
    seen = set()
    for s, _p, o in _all_patterns(clauses):
        for item in (s, o):
            if item[0] == _VAR and item[1] not in seen:
                seen.add(item[1])
                order.append(item[1])
    return tuple(order)


class _PathMatcher:
    """把属性路径 AST 求值为去重的节点对集合。

    边集合只来自构造时给定的事实并集（OntologyModel.triples：显式 + 派生）；
    序列取关系复合、选择取并集、逆向翻转节点对；p?/p* 的零次分支取
    “全部三元组中实际出现过的主语或宾语”上的恒等节点对，不引入新术语；
    p+/p* 按每个起点做带 visited 的深度优先搜索求传递闭包，访问过的节点
    不重复展开，环状数据上必然有限结束。
    各 AST 子树的结果按节点缓存，重复查询同一模型时求值过程完全一致。
    """

    __slots__ = ("_edges", "_nodes", "_cache")

    def __init__(self, facts) -> None:
        edges: dict = {}
        nodes: set = set()
        for fact in facts:
            edges.setdefault(fact.predicate, set()).add(
                (fact.subject, fact.object)
            )
            nodes.add(fact.subject)
            nodes.add(fact.object)
        self._edges = edges
        self._nodes = frozenset(nodes)
        self._cache: dict = {}

    def identity(self) -> frozenset:
        return frozenset((node, node) for node in self._nodes)

    def eval(self, tree: tuple) -> frozenset:
        cached = self._cache.get(tree)
        if cached is not None:
            return cached
        tag = tree[0]
        if tag == "edge":
            pairs = frozenset(self._edges.get(tree[1], ()))
        elif tag == "inv":
            pairs = frozenset((v, u) for u, v in self.eval(tree[1]))
        elif tag == "seq":
            left = self.eval(tree[1])
            right = self.eval(tree[2])
            # 以中段节点连接：先走左路径再走右路径
            right_by_mid: dict = {}
            for mid, end in right:
                right_by_mid.setdefault(mid, []).append(end)
            composed = set()
            for start, mid in left:
                for end in right_by_mid.get(mid, ()):  # 中段不接续即无复合结果
                    composed.add((start, end))
            pairs = frozenset(composed)
        elif tag == "alt":
            pairs = self.eval(tree[1]) | self.eval(tree[2])
        elif tag == "zeroone":
            pairs = self.eval(tree[1]) | self.identity()
        elif tag == "oneplus":
            pairs = self._closure_positive(self.eval(tree[1]))
        else:  # tag == "zero"
            base = self.eval(tree[1])
            pairs = self._closure_positive(base) | self.identity()
        self._cache[tree] = pairs
        return pairs

    @staticmethod
    def _closure_positive(base: frozenset) -> frozenset:
        """一层或多层的传递闭包：从每个起点沿 base 边做带 visited 的 DFS，
        环状数据上访问过的节点不会重复展开，必然有限结束。"""
        adjacency: dict = {}
        for start, end in base:
            adjacency.setdefault(start, []).append(end)
        reachable = set()
        for source in adjacency:
            seen = set()
            stack = list(adjacency[source])
            while stack:
                node = stack.pop()
                if node in seen:
                    continue
                seen.add(node)
                reachable.add((source, node))
                stack.extend(adjacency.get(node, ()))
        return frozenset(reachable)


def _match_patterns(matcher: _PathMatcher, bindings: List[dict], patterns) -> List[dict]:
    """对一组三元组模式按序做内连接，返回所有扩展后的绑定。"""
    for s, p, o in patterns:
        pairs = matcher.eval(p.tree)
        next_bindings: List[dict] = []
        for binding in bindings:
            for subj, obj in pairs:  # 节点对已去重，同一事实可被多个模式复用
                if s[0] == _VAR:
                    if s[1] in binding and subj != binding[s[1]]:
                        continue
                elif subj != s[1]:
                    continue
                extended = dict(binding)
                if s[0] == _VAR:
                    extended[s[1]] = subj
                # 同一模式内主语/宾语可能是同一变量（如 ?x p ?x）
                if o[0] == _VAR:
                    if o[1] in extended and obj != extended[o[1]]:
                        continue
                elif obj != o[1]:
                    continue
                if o[0] == _VAR:
                    extended[o[1]] = obj
                next_bindings.append(extended)
        bindings = next_bindings
        if not bindings:
            break
    return bindings


def _eval_filter(expr: tuple, binding: dict) -> bool:
    kind = expr[0]
    if kind == _EXPR_BOUND:
        return expr[1] in binding
    if kind == _EXPR_NOT_BOUND:
        return expr[1] not in binding

    def value_of(operand) -> Any:
        tag, name, _pos = operand
        if tag == _LIT:
            return name
        # 变量未绑定时等值/不等值比较均为假
        return binding.get(name)

    left = value_of(expr[1])
    right = value_of(expr[2])
    if left is None or right is None:
        return False
    equal = left == right
    return equal if kind == _EXPR_EQ else not equal


def _eval_clauses(matcher: _PathMatcher, clauses) -> List[dict]:
    """按子句顺序在 matcher 上求值，返回全部最终绑定（无匹配时为空列表）。

    SELECT 与 ASK 共用这一段求值逻辑：BGP 内连接、OPTIONAL 左连接、
    UNION 各分支独立匹配后合并、FILTER 按逻辑与过滤此前全部解。
    """
    bindings: List[dict] = [{}]
    for kind, patterns, expr in clauses:
        if kind == _CLAUSE_FILTER:
            bindings = [b for b in bindings if _eval_filter(expr, b)]
        elif kind == _CLAUSE_OPTIONAL:
            joined: List[dict] = []
            for binding in bindings:
                matches = _match_patterns(matcher, [dict(binding)], patterns)
                if matches:
                    joined.extend(matches)
                else:
                    # 无匹配：保留原绑定一次，块内新变量保持未绑定
                    joined.append(binding)
            bindings = joined
        elif kind == _CLAUSE_UNION:
            # 每个分支从当前绑定独立求值，结果取并集：同名变量与既有绑定
            # 冲突时该分支匹配自然落空，仅一分支绑定的变量随该分支保留。
            unioned: List[dict] = []
            for binding in bindings:
                for branch in patterns:
                    unioned.extend(_match_patterns(matcher, [dict(binding)], branch))
            bindings = unioned
        else:
            bindings = _match_patterns(matcher, bindings, patterns)
        if not bindings:
            break
    return bindings


def run_query(model, text) -> QueryResult:
    """在 model.triples 上执行查询，返回应用解序列修饰符后的 QueryResult。

    普通 SELECT 先按既有语义求值、投影、去重并按投影字典序排列。

    出现聚合项（'(COUNT/MIN/MAX(...) AS ?别名)'）或 GROUP BY 时走分组
    聚合路径：WHERE 先按既有语义求值与 FILTER 过滤，再按组键值把解分组；
    有 GROUP BY 时每个不同组键值输出一行（无解则无行），无 GROUP BY 时
    即使没有解也产生一个空组行（COUNT 为 0、MIN/MAX 为 None）。每行按
    投影顺序由组键值与聚合结果构成：COUNT(*) 统计组内解数（非负整数），
    COUNT(?v) 只统计 ?v 已绑定的解，COUNT(DISTINCT ?v) 再按绑定值去重；
    MIN(?v)/MAX(?v) 在组内已绑定的字符串值中按 Unicode 字典序取最小/
    最大，无已绑定时为 None。

    两条路径都先按投影去重并字典序排序，再有 ORDER BY 时做稳定排序
    （同键未绑定值先于绑定值，DESC 相反；多键按出现顺序比较，全相同
    则保留投影字典序），最后跳过 OFFSET 条并保留至多 LIMIT 条。
    """
    properties = frozenset(getattr(model, "declared_properties", ()))
    head, clauses, star, (group_keys, order_keys, limit, offset) = (
        _compile_query(text, properties)
    )

    matcher = _PathMatcher(model.triples)
    bindings = _eval_clauses(matcher, clauses)

    has_aggregate = any(item[0] == "a" for item in head)
    if not star and (has_aggregate or group_keys):
        rows = _aggregate_bindings(head, group_keys, bindings)
        projection = tuple(item[1] for item in head)
    else:
        if star:
            projection = _star_variables(clauses)
        else:
            projection = tuple(item[1] for item in head)
        rows = {
            tuple(binding.get(name) for name in projection) for binding in bindings
        }

    # None（未绑定）排在所有字符串之前，保证混合取值时字典序排序稳定。
    ordered = sorted(rows, key=_projection_sort_key)
    if order_keys:
        index = {name: i for i, name in enumerate(projection)}
        # Python 排序稳定：从最后一个排序键开始依次排序，多键按出现顺序
        # 生效，全部键相同的行保持此前的投影字典序。
        for name, descending, _pos in reversed(order_keys):
            column = index[name]
            ordered.sort(
                key=lambda row, c=column: _projection_sort_key((row[c],)),
                reverse=descending,
            )
    if offset:
        ordered = ordered[offset:]
    if limit is not None:
        ordered = ordered[:limit]
    return QueryResult(projection, tuple(ordered))


def _aggregate_bindings(head, group_keys, bindings):
    """把求值得到的绑定按组键分组并计算聚合，返回行集合（未排序）。

    组键在绑定中未绑定时以 None 作为组值，所有未绑定解归入同一组。
    无 GROUP BY 时所有解属于同一个组，且即使解列表为空也产生一行；
    有 GROUP BY 但没有任何解时不产生行。
    """
    key_names = tuple(name for name, _pos in group_keys)
    aggs = [item for item in head if item[0] == "a"]

    groups: dict = {}
    if key_names:
        for binding in bindings:
            key = tuple(binding.get(name) for name in key_names)
            groups.setdefault(key, []).append(binding)
    else:
        # 单一空键组：没有解时同样保留该组，产生一行聚合结果。
        groups[()] = list(bindings)

    rows = set()
    for key, members in groups.items():
        key_values = dict(zip(key_names, key))
        row = []
        for item in head:
            if item[0] == "v":
                row.append(key_values.get(item[1]))
            else:
                _tag, alias, kind, operand, _pos = item
                row.append(_compute_aggregate(kind, operand, members))
        rows.add(tuple(row))
    return rows


def _compute_aggregate(kind: str, operand, members: List[dict]):
    """在一个组的解序列上计算单个聚合值。

    COUNT(*) 统计全部解；COUNT(?v) 只统计变量已绑定的解；
    COUNT(DISTINCT ?v) 在已绑定值上按值去重计数；
    MIN/MAX 在已绑定字符串值中按 Unicode 字典序取极值，无值为 None。
    """
    if kind == _AGG_COUNT:
        if operand is None:
            return len(members)
        return sum(1 for binding in members if binding.get(operand) is not None)
    if kind == _AGG_COUNT_DISTINCT:
        return len(
            {
                binding[operand]
                for binding in members
                if binding.get(operand) is not None
            }
        )
    values = [
        binding[operand]
        for binding in members
        if binding.get(operand) is not None
    ]
    if not values:
        return None
    return min(values) if kind == _AGG_MIN else max(values)


def _projection_sort_key(row) -> tuple:
    """投影字典序排序键：None（未绑定）排在所有字符串之前。"""
    return tuple((0, "") if value is None else (1, value) for value in row)


def run_ask(model, text) -> bool:
    """在 model.triples 上执行 ASK 查询：至少一个最终解返回 True，否则 False。"""
    properties = frozenset(getattr(model, "declared_properties", ()))
    clauses = _compile_ask(text, properties)
    matcher = _PathMatcher(model.triples)
    return bool(_eval_clauses(matcher, clauses))


def run_construct(model, text) -> tuple:
    """在 model.triples 上执行 CONSTRUCT 查询，返回去重排序后的 Triple 元组。

    WHERE 模式体与 SELECT/ASK 同语义求值；对每个最终绑定逐项实例化模板，
    主语或宾语变量未绑定时跳过该模板，其余模板继续。生成的三元组不写回
    模型，重复执行同一模型与查询结果一致。
    """
    from .model import Triple  # 延迟导入，避免与 model 模块循环依赖

    properties = frozenset(getattr(model, "declared_properties", ()))
    templates, clauses = _compile_construct(text, properties)
    matcher = _PathMatcher(model.triples)
    bindings = _eval_clauses(matcher, clauses)

    generated = set()
    for binding in bindings:
        for s, predicate, o in templates:
            subject = s[1] if s[0] == _LIT else binding.get(s[1])
            object_ = o[1] if o[0] == _LIT else binding.get(o[1])
            if subject is None or object_ is None:
                # 主语或宾语变量未绑定：不生成该三元组，继续处理其余模板
                continue
            generated.add(Triple(subject, predicate, object_))
    return tuple(sorted(generated))


def run_describe(model, text) -> tuple:
    """在 model.triples 上执行 DESCRIBE 查询，返回去重排序后的 Triple 元组。

    WHERE 模式体与 SELECT/ASK 同语义求值：'*' 对每个最终绑定取其当前已
    绑定的全部变量值作为待描述名称；指定变量时分别取其绑定值，未绑定变量
    在本次解中忽略。对每个待描述名称 N，收集显式与推理三元组并集中主语或
    宾语为 N 的全部三元组，不因来源是显式事实还是某条规则而有所区别；全部
    解的描述合并后按 (主语, 谓语, 宾语) 字典序去重排序。无匹配绑定、变量
    均未绑定或描述集合为空时返回空元组。查询不修改模型与已有证明，重复执行
    同一模型与查询结果一致。
    """
    properties = frozenset(getattr(model, "declared_properties", ()))
    projection, clauses, star = _compile_describe(text, properties)
    if star:
        projection = _star_variables(clauses)

    matcher = _PathMatcher(model.triples)
    bindings = _eval_clauses(matcher, clauses)

    names = set()
    if star:
        # 每个最终绑定只描述其中当前已绑定的变量值（与投影顺序无关）
        for binding in bindings:
            names.update(binding.values())
    else:
        for binding in bindings:
            for name in projection:
                value = binding.get(name)
                if value is not None:
                    names.add(value)

    described = set()
    for triple in model.triples:
        if triple.subject in names or triple.object in names:
            described.add(triple)
    return tuple(sorted(described))

"""本体模型：解析结果的只读视图。

模型内部以不可变集合保存数据，所有读取接口返回新的不可变序列，
不会修改已解析的数据，因此同一模型可重复读取且结果稳定。
"""

from __future__ import annotations

import itertools
from typing import Iterator, Optional, Tuple

from .errors import OntologyError
from .query import (
    QueryResult,
    run_ask,
    run_construct,
    run_describe,
    run_query,
)

_VARIABLE_PREFIX = "?"

_EXPLICIT_KIND = "explicit"
_RULE_KIND = "rule"


def _is_variable(value: str) -> bool:
    return value.startswith(_VARIABLE_PREFIX)


class Triple(tuple):
    """一条三元组 (subject, predicate, object)，按字典序可比较。"""

    __slots__ = ()

    def __new__(cls, subject: str, predicate: str, object_: str) -> "Triple":
        return super().__new__(cls, (subject, predicate, object_))

    @property
    def subject(self) -> str:
        return self[0]

    @property
    def predicate(self) -> str:
        return self[1]

    @property
    def object(self) -> str:
        return self[2]

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"Triple({self[0]!r}, {self[1]!r}, {self[2]!r})"


class DerivedTriple:
    """一条推理结论：三元组 + 来源规则 id。"""

    __slots__ = ("_triple", "_rule_id")

    def __init__(self, triple: Triple, rule_id) -> None:
        self._triple = triple
        self._rule_id = rule_id

    @property
    def triple(self) -> Triple:
        return self._triple

    @property
    def subject(self) -> str:
        return self._triple.subject

    @property
    def predicate(self) -> str:
        return self._triple.predicate

    @property
    def object(self) -> str:
        return self._triple.object

    @property
    def rule_id(self):
        return self._rule_id

    def __iter__(self) -> Iterator:
        return iter((self._triple, self._rule_id))

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, DerivedTriple)
            and self._triple == other._triple
            and self._rule_id == other._rule_id
        )

    def __hash__(self) -> int:
        return hash((self._triple, self._rule_id))

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return f"DerivedTriple({self._triple!r}, rule_id={self._rule_id!r})"


class Proof:
    """一条三元组的证明树节点（只读快照）。

    - kind 为 "explicit"：triple 是输入中的显式事实，ruleId 为 None，
      premises 为空元组；
    - kind 为 "rule"：triple 由规则 ruleId 经具体常量替换后推出，
      premises 按该规则 if 模式的原顺序给出各前提的证明节点，
      沿 premises 可一直追到显式叶子。
    所有公开属性只读；相等性按 kind/triple/ruleId/premises 结构比较。
    """

    __slots__ = ("_kind", "_triple", "_rule_id", "_premises")

    def __init__(self, kind: str, triple: Triple, rule_id, premises) -> None:
        self._kind = kind
        self._triple = triple
        self._rule_id = rule_id
        self._premises = tuple(premises)

    @property
    def kind(self) -> str:
        """证明种类："explicit" 或 "rule"。"""
        return self._kind

    @property
    def triple(self) -> Triple:
        """本节点证明的三元组。"""
        return self._triple

    @property
    def ruleId(self):
        """推出该三元组的规则 id（保留原始字符串或整数）；显式事实为 None。"""
        return self._rule_id

    @property
    def premises(self) -> Tuple["Proof", ...]:
        """前提证明节点元组，按规则 if 模式的原顺序排列。"""
        return self._premises

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, Proof)
            and self._kind == other._kind
            and self._triple == other._triple
            and self._rule_id == other._rule_id
            and self._premises == other._premises
        )

    def __hash__(self) -> int:
        return hash((self._kind, self._triple, self._rule_id, self._premises))

    def __repr__(self) -> str:  # pragma: no cover - 便于调试
        return (
            f"Proof(kind={self._kind!r}, triple={self._triple!r}, "
            f"ruleId={self._rule_id!r}, premises={self._premises!r})"
        )


def _leaf_count(proof: Proof) -> int:
    """证明长度：树中显式叶子的数量。"""
    if proof.kind == _EXPLICIT_KIND:
        return 1
    return sum(_leaf_count(premise) for premise in proof.premises)


def _proof_sort_key(proof: Proof):
    """稳定排序键：kind、ruleId 的字符串形式、节点 triple、premises 顺序。"""
    return (
        proof.kind,
        str(proof.ruleId),
        proof.triple,
        tuple(_proof_sort_key(premise) for premise in proof.premises),
    )


def _unify_then(pattern, triple: Triple):
    """把 then 模式与基三元组对齐，返回变量→常量绑定；不一致时返回 None。"""
    s, p, o = pattern
    if p != triple.predicate:
        return None
    binding = {}
    for term, value in ((s, triple.subject), (o, triple.object)):
        if _is_variable(term):
            if term in binding:
                if binding[term] != value:
                    return None
            else:
                binding[term] = value
        elif term != value:
            return None
    return binding


def _instantiate(pattern, binding) -> Triple:
    """按绑定把三元组模式替换为基三元组（模式中的变量均已绑定）。"""
    s, p, o = pattern
    return Triple(
        binding.get(s, s) if _is_variable(s) else s,
        p,
        binding.get(o, o) if _is_variable(o) else o,
    )


class OntologyModel:
    """解析与推理完成后的本体模型。

    - explicit_triples：显式三元组，按 (主语, 谓语, 宾语) 字典序排列。
    - derived_triples：推理结论，同样按字典序排列，每条带来源规则 id。
    - entails(s, p, o)：判断单条三元组是否被蕴含（显式或推理得出）。
    - explain(s, p, o)：给出该三元组的全部最短完整证明（Proof 元组）。
    - ask(text)：SPARQL 风格 ASK 存在性查询，返回布尔值。
    - construct(text)：SPARQL 风格 CONSTRUCT 查询，返回生成的 Triple 元组。
    - describe(text)：SPARQL 风格 DESCRIBE 查询，返回绑定值相关的全部
      三元组（显式与推理并集），按字典序去重排序的只读 Triple 元组。
    - declared_properties：本体中已声明的属性名（查询谓语/属性路径据此校验）。
    所有读取接口均返回新对象，不改变模型内部数据。
    """

    __slots__ = ("_explicit", "_derived", "_facts", "_source", "_properties", "_rules")

    def __init__(self, explicit, derived, properties=frozenset(), rules=()) -> None:
        # explicit / derived: dict[Triple, rule_id 或 None]
        # rules: (rule_id, if 模式, then 模式) 元组序列，模式为 (s, p, o) 字符串三元组
        self._explicit = frozenset(explicit)
        self._derived = frozenset(
            DerivedTriple(triple, rule_id) for triple, rule_id in derived.items()
        )
        self._facts = frozenset(explicit) | frozenset(derived)
        self._source = dict(derived)
        self._properties = frozenset(properties)
        self._rules = tuple(
            (
                rule_id,
                tuple(tuple(pattern) for pattern in if_patterns),
                tuple(tuple(pattern) for pattern in then_patterns),
            )
            for rule_id, if_patterns, then_patterns in rules
        )

    @property
    def explicit_triples(self) -> Tuple[Triple, ...]:
        """显式三元组，按字典序稳定排列。"""
        return tuple(sorted(self._explicit))

    @property
    def derived_triples(self) -> Tuple[DerivedTriple, ...]:
        """推理结论（含来源规则 id），按三元组字典序稳定排列。"""
        return tuple(sorted(self._derived, key=lambda d: (d.triple, str(d.rule_id))))

    @property
    def triples(self) -> Tuple[Triple, ...]:
        """全部三元组（显式 + 推理），按字典序稳定排列。"""
        return tuple(sorted(self._facts))

    @property
    def declared_properties(self) -> Tuple[str, ...]:
        """本体中已声明的属性名，按字典序稳定排列。"""
        return tuple(sorted(self._properties))

    def entails(self, subject: str, predicate: str, object_: str) -> bool:
        """判断 (subject, predicate, object_) 是否被当前模型蕴含。"""
        return Triple(subject, predicate, object_) in self._facts

    def source_rule(self, subject: str, predicate: str, object_: str) -> Optional[object]:
        """返回推理出该三元组的规则 id；显式或未知三元组返回 None。"""
        return self._source.get(Triple(subject, predicate, object_))

    def explain(self, subject: str, predicate: str, object_) -> Tuple[Proof, ...]:
        """返回 (subject, predicate, object_) 的全部最短完整证明。

        - 显式事实：返回恰一个 kind 为 "explicit" 的证明（即使它同时也能
          被规则推出，显式证明优先）；
        - 推理结论：返回全部显式叶子数最少的完整证明；规则有多个 then
          或不同替换能推出目标时全部保留，按 kind、ruleId 的字符串形式、
          节点 triple 和 premises 顺序稳定排列，重复树去重；
        - 未被蕴含的三元组：返回空元组。
        证明不依赖推理循环（成环规则上有限结束）。subject、predicate、
        object 任一不是字符串时抛出 OntologyError。
        """
        for position, (name, value) in enumerate(
            (("subject", subject), ("predicate", predicate), ("object", object_)),
            start=1,
        ):
            if not isinstance(value, str):
                raise OntologyError(
                    f"explain 的第 {position} 个参数（{name}）必须是字符串，"
                    f"收到 {value!r}"
                )
        goal = Triple(subject, predicate, object_)
        if goal in self._explicit:
            return (Proof(_EXPLICIT_KIND, goal, None, ()),)
        if goal not in self._facts:
            return ()
        proofs = self._prove(goal, frozenset())
        if not proofs:  # pragma: no cover - 推理结论必有证明，此处仅作防御
            return ()
        best = min(_leaf_count(proof) for proof in proofs)
        chosen = [proof for proof in proofs if _leaf_count(proof) == best]
        unique = list(dict.fromkeys(chosen))
        unique.sort(key=_proof_sort_key)
        return tuple(unique)

    # ---------- 证明枚举（后向链接，按路径阻断循环） ----------

    def _prove(self, goal: Triple, blocked: frozenset) -> list:
        """枚举 goal 的全部无环证明（未按叶子数过滤）。

        blocked 为当前根到此节点路径上已出现的目标三元组；前提落入
        blocked 的替换被丢弃，因此成环规则上证明枚举必然有限结束，
        且不会返回依赖循环的证明。
        """
        if goal in self._explicit:
            return [Proof(_EXPLICIT_KIND, goal, None, ())]
        if goal not in self._facts:
            return []
        blocked = blocked | {goal}
        fact_list = sorted(self._facts)
        proofs = []
        for rule_id, if_patterns, then_patterns in self._rules:
            for then in then_patterns:
                partial = _unify_then(then, goal)
                if partial is None:
                    continue
                for binding in self._match(if_patterns, fact_list, partial):
                    premises = tuple(
                        _instantiate(pattern, binding) for pattern in if_patterns
                    )
                    if any(triple in blocked for triple in premises):
                        continue
                    options = []
                    for triple in premises:
                        sub = self._prove(triple, blocked)
                        if not sub:
                            break
                        options.append(sub)
                    else:
                        for combo in itertools.product(*options):
                            proofs.append(Proof(_RULE_KIND, goal, rule_id, combo))
        return proofs

    @staticmethod
    def _match(patterns, fact_list, initial) -> list:
        """从给定部分绑定出发，对 if 模式按序做连接匹配（与推理同序）。"""
        bindings = [dict(initial)]
        for s, p, o in patterns:
            next_bindings = []
            for binding in bindings:
                for fact in fact_list:
                    if fact.predicate != p:
                        continue
                    if _is_variable(s):
                        if s in binding and fact.subject != binding[s]:
                            continue
                    elif fact.subject != s:
                        continue
                    extended = dict(binding)
                    if _is_variable(s):
                        extended[s] = fact.subject
                    if _is_variable(o):
                        if o in extended and fact.object != extended[o]:
                            continue
                    elif fact.object != o:
                        continue
                    if _is_variable(o):
                        extended[o] = fact.object
                    next_bindings.append(extended)
            bindings = next_bindings
            if not bindings:
                break
