        f"或字符串/非负整数常量，遇到 {tok.value!r}（字符位置 {tok.pos}）"
    )

def _parse_having_aggregate(self, tokens, i):
    """解析 HAVING 中的内联聚合调用（不带 AS 别名），tokens[i] 为函数名。"""
    func = tokens[i]
