        if distinct:
            raise OntologyError(
                f"{func.value} 不支持 DISTINCT 参数：只接受单个变量"
                f"（字符位置 {arg_tok.pos}）"
            )
        if arg_tok.kind != _TOK_VAR:
            raise OntologyError(
                f"{func.value} 的参数形式非法：括号内必须且只能出现一个变量，"
                f"遇到 {arg_tok.value!r}（字符位置 {arg_tok.pos}）"
