    i += 1

    if i >= len(tokens) or tokens[i].kind != _TOK_RPAREN:
        pos = tokens[i].pos if i < len(tokens) else start
        raise OntologyError(
            f"{func.value} 聚合参数或嵌套形式非法：参数只能是 '*'、"
            f"DISTINCT ?变量 或单个变量（字符位置 {pos}）"
        )
    i += 1
    return (_HVAL_AGG, kind, operand, start), i

