def _parse_solution_modifiers(self, star: bool, head: list) -> tuple:
    """解析 WHERE 右花括号之后的修饰符序列。

    返回 (分组键, HAVING 条件, 排序键, LIMIT, OFFSET)：分组键为
    (变量名, 字符位置) 元组，HAVING 条件为条件元组元组，排序键为
    (变量名, 是否降序, 字符位置) 元组，LIMIT 缺省为 None（不截断），
    OFFSET 缺省为 0。self._last 此时是模式体的右花括号。修饰符按
    GROUP BY、HAVING、ORDER BY、LIMIT、OFFSET 的顺序各至多出现一次：
    HAVING 只能位于 GROUP BY 之后（无 GROUP BY 时直接位于花括号之后），
    不得出现在 ORDER BY/LIMIT/OFFSET 之后。
    """
    tokens = _tail_tokens(self._text, self._last.pos + 1)
    group_keys: List[tuple] = []
    having: List[tuple] = []
    order_keys: List[tuple] = []
    limit = None
    offset = 0
    group_pos = None
    having_pos = None
    # stage：0 可出现 GROUP/HAVING/ORDER，1 可出现 HAVING/ORDER/LIMIT，
    # 2 可出现 ORDER/LIMIT（HAVING 已消费），3 可出现 LIMIT/OFFSET，
    # 4 只能出现 OFFSET，5 全部结束
    stage = 0
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok.kind == _TOK_NAME and tok.value == "HAVING":
            if having:
                raise OntologyError(
                    f"修饰符 HAVING 重复：HAVING 至多出现一次"
                    f"（字符位置 {tok.pos}）"
                )
            if stage > 1:
                raise OntologyError(
                    f"修饰符 HAVING 顺序错误：HAVING 只能位于 GROUP BY 之后、"
                    f"ORDER BY 之前（字符位置 {tok.pos}）"
                )
            having_pos = tok.pos
            having, i = self._parse_having(tokens, i, head, group_keys)
            stage = 2
            continue
        if tok.kind == _TOK_NAME and tok.value in _MODIFIER_WORDS:
            index = _MODIFIER_WORDS.index(tok.value)
            # HAVING 占去 GROUP 与 ORDER 之间的一个位置：stage 2 表示
            # HAVING 已消费，此时允许的首个关键字是 ORDER（索引 1）。
            effective_stage = stage - 1 if stage == 2 else stage
            if index < effective_stage:
                raise OntologyError(
                    f"修饰符 {tok.value} 重复或顺序错误：应按 GROUP BY、"
                    f"HAVING、ORDER BY、LIMIT、OFFSET 的顺序各出现一次"
                    f"（字符位置 {tok.pos}）"
                )
            stage = index + 1
            if tok.value == "GROUP":
                group_pos = tok.pos
                group_keys, i = self._parse_group_by(tokens, i)
                stage = 1
            elif tok.value == "ORDER":
                order_keys, i = self._parse_order_by(tokens, i)
            elif tok.value == "LIMIT":
                limit, i = self._parse_int_modifier(tokens, i)
            else:
                offset, i = self._parse_int_modifier(tokens, i)
        elif (
            tok.kind == _TOK_NAME
            and tok.value != tok.value.upper()
            and tok.value.upper()
            in _MODIFIER_WORDS + _ORDER_WORDS + _HAVING_WORDS
            + _AGGREGATE_WORDS + ("DISTINCT",)
        ):
            raise OntologyError(
                f"关键字 {tok.value!r} 大小写不合规：只接受大写形式"
                f"（字符位置 {tok.pos}）"
            )
        else:
            raise OntologyError(
                f"右花括号后存在未知语句成分 {tok.value!r}"
                f"（字符位置 {tok.pos}）"
            )
    if star and group_keys:
        raise OntologyError(
            "分组查询不得使用星号投影 '*'（字符位置 "
            f"{group_pos if group_pos is not None else 0}）"
        )
    if star and having:
        raise OntologyError(
            "HAVING 只能用于带聚合投影或 GROUP BY 的 SELECT，"
            f"不得与星号投影 '*' 同时使用（字符位置 {having_pos}）"
        )
    return (
        tuple(group_keys),
        tuple(having),
        tuple(order_keys),
        limit,
        offset,
    )

